@startuml

class HospitalHouseMD {
  + name : string
}

class Patient {
  + name : string
  + symptoms : string
}

class Doctor {
  + name : string
  + practitionerNumber : int
}

class Diagnosis {
  + description : string
  + date : date
}

class Treatment {
  + name : string
  + description : string
}

class TreatmentStage {
  + stageNumber : int
}

enum PriorityScore {
  High
  Low
}

class Illness {
  + name : string
  + priority : PriorityScore
}

class ConsentForm {
  + dateSigned : date
  + isRetracted : boolean
}

class TreatmentRecord {
  + dateStarted : date
  + dateCompleted : date
}

HospitalHouseMD "1" o-- "*" Patient
Patient "1" -- "1..*" Doctor
Doctor "1" -- "0..*" Diagnosis
Patient "1" -- "0..*" Diagnosis
Diagnosis "1" -- "1" Illness
Illness "1" -- "*" Treatment
Diagnosis "1" -- "1..*" TreatmentRecord
TreatmentRecord "1" -- "1" Treatment
TreatmentRecord "1" -- "1" TreatmentStage
Patient "1" -- "0..1" ConsentForm
ConsentForm "1" -- "1..*" TreatmentRecord

@enduml

